#!/usr/bin/env node
// Generated by OrchestKit Claude Plugin
// Created: 2026-10-31
/**
 * measure-hook-processes.mjs: processes one tool call starts, measured live.
 *
 * For each tool (Bash, Edit, Read by default) this replays the success path
 * Claude Code fires (PreToolUse, PostToolUse, PostToolBatch): every
 * `type: "command"` entry in hooks.json whose matcher matches the tool is run
 * once, exactly as CC would launch it (command + args, payload on stdin,
 * ${CLAUDE_PLUGIN_ROOT} substituted). Async entries are run too: CC still
 * starts a process for them, it just does not wait.
 *
 * Two numbers per tool:
 *   hook processes   entries CC launches (one node process each)
 *   child processes  processes those hooks fork through node:child_process
 *                    (git, gh, shells, nested node), counted by the
 *                    lib/count-child-processes.cjs preload
 *
 * Runs sequentially in a throwaway HOME and git repo, so it never writes the
 * operator's ~/.claude analytics. Not a test: it prints numbers, and with
 * --out writes them as JSON. Exit 0 unless a hook could not be launched.
 *
 * Usage:
 *   node scripts/measure-hook-processes.mjs [--hooks <hooks.json>]
 *        [--plugin-root <dir>] [--tools Bash,Edit,Read] [--out <file.json>]
 *
 * Defaults: --hooks src/hooks/hooks.json, --plugin-root src/ (so
 * ${CLAUDE_PLUGIN_ROOT}/hooks/bin/run-hook.mjs resolves to this tree's runner
 * and src/hooks/dist bundles).
 */
import { spawnSync, execFileSync } from 'node:child_process';
import { mkdtempSync, mkdirSync, readFileSync, writeFileSync, existsSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join, dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = dirname(fileURLToPath(import.meta.url));
const HOOKS_DIR = join(__dirname, '..');
const PRELOAD = join(__dirname, 'lib', 'count-child-processes.cjs');
const SUCCESS_EVENTS = ['PreToolUse', 'PostToolUse', 'PostToolBatch'];

export function matches(matcher, tool) {
  if (matcher === undefined || matcher === '' || matcher === '*') return true;
  if (/^[\w|]+$/.test(matcher)) return matcher.split('|').includes(tool);
  return new RegExp(`^(?:${matcher})$`).test(tool);
}

/**
 * Command entries CC launches for one tool call on the success path.
 *
 * CC runs an identical command (same command + args) once per event even
 * when two matching groups list it. Calibrated 2026-10-31 against
 * `claude -p --debug-file` on CC 2.1.316: lifecycle/webhook-forwarder sits in
 * the per-tool PreToolUse group and the matcher-less one, and fires once.
 */
export function entriesFor(hooksDoc, tool, events = SUCCESS_EVENTS) {
  const out = [];
  for (const event of events) {
    const seen = new Set();
    for (const group of hooksDoc.hooks?.[event] ?? []) {
      if (!matches(group.matcher, tool)) continue;
      for (const h of group.hooks ?? []) {
        if (h.type !== 'command') continue;
        const key = JSON.stringify([h.command, h.args ?? []]);
        if (seen.has(key)) continue;
        seen.add(key);
        out.push({ event, matcher: group.matcher ?? '*', hook: h });
      }
    }
  }
  return out;
}

function toolInput(tool, repo) {
  const file = join(repo, 'src', 'example.ts');
  switch (tool) {
    case 'Bash':
      return { input: { command: 'git status', description: 'Show status' }, response: { stdout: '', stderr: '', interrupted: false } };
    case 'Edit':
      return {
        input: { file_path: file, old_string: 'one', new_string: 'two' },
        response: { filePath: file, oldString: 'one', newString: 'two', structuredPatch: [] },
      };
    case 'Write':
      return { input: { file_path: file, content: 'export const two = 2;\n' }, response: { type: 'update', filePath: file } };
    case 'Read':
      return { input: { file_path: file }, response: { type: 'text', file: { filePath: file, content: 'export const one = 1;\n' } } };
    default:
      return { input: {}, response: {} };
  }
}

function payload(event, tool, repo, home) {
  const { input, response } = toolInput(tool, repo);
  const base = {
    session_id: 'measure-hook-processes',
    transcript_path: join(home, 'transcript.jsonl'),
    cwd: repo,
    hook_event_name: event,
    permission_mode: 'default',
  };
  if (event === 'PostToolBatch') {
    return { ...base, tool_calls: [{ tool_name: tool, tool_input: input, tool_use_id: 'toolu_measure' }] };
  }
  const p = { ...base, tool_name: tool, tool_input: input, tool_use_id: 'toolu_measure' };
  if (event === 'PostToolUse') p.tool_response = response;
  return p;
}

function makeSandbox() {
  const root = mkdtempSync(join(tmpdir(), 'ork-hook-procs-'));
  const home = join(root, 'home');
  const repo = join(root, 'repo');
  mkdirSync(join(home, '.claude'), { recursive: true });
  mkdirSync(join(repo, 'src'), { recursive: true });
  writeFileSync(join(repo, 'src', 'example.ts'), 'export const one = 1;\n');
  execFileSync('git', ['init', '-q', repo]);
  return { root, home, repo };
}

function runEntry(entry, tool, sandbox, pluginRoot) {
  const countFile = join(sandbox.root, `count-${process.hrtime.bigint()}.tsv`);
  const sub = (s) => s.replaceAll('${CLAUDE_PLUGIN_ROOT}', pluginRoot);
  const args = (entry.hook.args ?? []).map(sub);
  const command = sub(entry.hook.command);
  const env = {
    ...process.env,
    HOME: sandbox.home,
    CLAUDE_PROJECT_DIR: sandbox.repo,
    CLAUDE_PLUGIN_ROOT: pluginRoot,
    CLAUDE_SESSION_ID: 'measure-hook-processes',
    ORK_SPAWN_COUNT_FILE: countFile,
    NODE_OPTIONS: `${process.env.NODE_OPTIONS ?? ''} --require ${PRELOAD}`.trim(),
  };
  const t = process.hrtime.bigint();
  const r = spawnSync(command, args, {
    cwd: sandbox.repo,
    env,
    input: JSON.stringify(payload(entry.event, tool, sandbox.repo, sandbox.home)),
    timeout: (entry.hook.timeout ?? 15) * 1000,
    encoding: 'utf8',
    shell: args.length === 0,
  });
  const ms = Number(process.hrtime.bigint() - t) / 1e6;
  const lines = existsSync(countFile) ? readFileSync(countFile, 'utf8').split('\n').filter(Boolean) : [];
  const children = lines.map((l) => l.split('\t')[2]);
  return {
    event: entry.event,
    matcher: entry.matcher,
    async: Boolean(entry.hook.async),
    handler: args[1] ?? command,
    exit: r.status,
    error: r.error ? String(r.error.message) : undefined,
    ms: Math.round(ms),
    children,
  };
}

export function measureTool(hooksDoc, tool, pluginRoot) {
  const sandbox = makeSandbox();
  try {
    const runs = entriesFor(hooksDoc, tool).map((e) => runEntry(e, tool, sandbox, pluginRoot));
    const childCount = runs.reduce((n, r) => n + r.children.length, 0);
    return {
      tool,
      hookProcesses: runs.length,
      childProcesses: childCount,
      total: runs.length + childCount,
      syncMs: runs.filter((r) => !r.async).reduce((n, r) => n + r.ms, 0),
      runs,
    };
  } finally {
    rmSync(sandbox.root, { recursive: true, force: true });
  }
}

function arg(name, fallback) {
  const i = process.argv.indexOf(name);
  return i > -1 ? process.argv[i + 1] : fallback;
}

function main() {
  const hooksPath = resolve(arg('--hooks', join(HOOKS_DIR, 'hooks.json')));
  const pluginRoot = resolve(arg('--plugin-root', join(HOOKS_DIR, '..')));
  const tools = arg('--tools', 'Bash,Edit,Read').split(',');
  const out = arg('--out');
  const hooksDoc = JSON.parse(readFileSync(hooksPath, 'utf8'));

  const results = tools.map((t) => measureTool(hooksDoc, t, pluginRoot));
  for (const r of results) {
    console.log(`${r.tool.padEnd(5)} hook processes ${String(r.hookProcesses).padStart(3)}  child processes ${String(r.childProcesses).padStart(3)}  total ${String(r.total).padStart(3)}  sync wall ${r.syncMs} ms`);
    for (const run of r.runs) {
      const kids = run.children.length ? `  forks: ${run.children.join(',')}` : '';
      const err = run.error ? `  ERROR ${run.error}` : '';
      console.log(`      ${run.event.padEnd(13)} ${run.async ? 'async' : 'sync '} ${run.handler}  exit=${run.exit} ${run.ms} ms${kids}${err}`);
    }
  }
  if (out) {
    const doc = {
      measured_at: new Date().toISOString(),
      node: process.version,
      hooks_json: hooksPath,
      path: 'success (PreToolUse + PostToolUse + PostToolBatch, batch of one)',
      results: results.map(({ runs, ...rest }) => ({
        ...rest,
        runs: runs.map(({ handler, event, async, exit, ms, children }) => ({ event, handler, async, exit, ms, children })),
      })),
    };
    writeFileSync(out, `${JSON.stringify(doc, null, 2)}\n`);
    console.log(`wrote ${out}`);
  }
  return results.some((r) => r.runs.some((x) => x.error)) ? 1 : 0;
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  process.exit(main());
}
